using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
namespace Cibio.RPG
{
 public sealed class RpgReview09:MonoBehaviour
 {
  RpgGame g;RpgActor h;string folder;int frame;readonly List<string> checks=new();
  void Check(bool ok,string description){checks.Add((ok?"PASS ":"FAIL ")+description);File.WriteAllLines(Path.Combine(folder,"Ascendente-09.txt"),checks);if(!ok)throw new InvalidOperationException(description);}
  public IEnumerator Run(string path)
  {
   folder=path;Directory.CreateDirectory(folder);g=GetComponent<RpgGame>();yield return new WaitForSecondsRealtime(.8f);ScreenCapture.CaptureScreenshot(Path.Combine(folder,"Menu09.png"));yield return new WaitForSecondsRealtime(.2f);g.StartGame(false);g.reviewPose=true;h=g.world.hero;
   try{GetComponent<RpgVerification>().RunChecks(folder);g.StartGame(false);g.reviewPose=true;RpgAudio.Instance.suppressOneShots=true;Checks();}catch(Exception ex){Debug.LogException(ex);Application.Quit(2);yield break;}finally{RpgAudio.Instance.suppressOneShots=false;}
   h.GetComponent<RpgPowerForm>().StopAllCoroutines();foreach(var fx in UnityEngine.Object.FindObjectsByType<RpgEffects>())Destroy(fx.gameObject);foreach(var fx in UnityEngine.Object.FindObjectsByType<RpgProjectile>())Destroy(fx.gameObject);yield return null;Reset();g.messageUntil=0;g.SnapCamera();yield return new WaitForSecondsRealtime(.4f);ScreenCapture.CaptureScreenshot(Path.Combine(folder,"HUD09.png"));yield return new WaitForSecondsRealtime(.15f);
   Time.captureFramerate=24;g.HandleTransformInput(true);yield return Frames(80,Vector2.zero);g.HandleTransformInput(false);yield return Frames(32,Vector2.zero);g.HandleTransformInput(true);yield return Frames(46,Vector2.zero);g.HandleTransformInput(false);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,"Ascendente09.png"));yield return new WaitForEndOfFrame();
   var atlasReport=new List<string>();h.transforming=0;
   foreach(int d in new[]{0,1,2,3})foreach(string action in new[]{"idle","walk","run","jump","slash","thrust","backslash","spellcast","flight","hurt"})
   {
    h.direction=d;h.flightHeight=action=="flight"?2.2f:0;int count=RpgArt.FrameCount("HeroAscendant",action);for(int f=0;f<count;f++){h.Pose(action,f);h.GetComponent<RpgPowerForm>().Refresh(1/24f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,$"Atlas09_{d}_{action}_{f:D2}.png"));atlasReport.Add($"PASS direction={d} action={action} frame={f}");}
   }
   File.WriteAllLines(Path.Combine(folder,"Quadros-09.txt"),atlasReport);h.buff=16;h.formStage=2;h.energy=100;h.flightHeight=0;h.direction=3;h.facing=Vector2.right;h.transform.position=new Vector2(-16,-2);h.velocity=Vector2.zero;h.Pose("idle",0);g.SnapCamera();g.ToggleFlight();yield return Frames(16,Vector2.zero);yield return Frames(40,Vector2.right,true);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,"Sonic09.png"));yield return new WaitForEndOfFrame();yield return Frames(10,Vector2.right,true);yield return Frames(12,Vector2.right,false,true);h.Land();yield return Frames(20,Vector2.zero);
   h.transform.position=new Vector2(0,-10);h.energy=100;h.facing=Vector2.down;h.direction=2;g.SnapCamera();h.attackTimer=h.powerPose=0;for(int i=0;i<3;i++){h.Attack();yield return Frames(17,Vector2.zero);}h.energy=100;g.waveCooldown=0;g.Wave();yield return Frames(24,Vector2.zero);h.powerPose=0;h.energy=100;g.boltCooldown=0;g.Bolt();yield return Frames(20,Vector2.zero);
   Time.captureFramerate=0;Reset();var capture=g.lens.gameObject.AddComponent<RpgAudioCapture>();g.HandleTransformInput(true);yield return Live(3.35f,Vector2.zero);g.HandleTransformInput(false);yield return Live(1.3f,Vector2.zero);g.HandleTransformInput(true);yield return Live(1.85f,Vector2.zero);g.HandleTransformInput(false);h.energy=100;h.transform.position=new Vector2(-16,-2);g.ToggleFlight();yield return Live(.5f,Vector2.zero);yield return Live(1.85f,Vector2.right,true);h.Land();yield return Live(1,Vector2.zero);capture.Save(Path.Combine(folder,"Audio09.wav"));File.WriteAllText(Path.Combine(folder,"Audio09.txt"),"Capture real-time; peak="+capture.peak.ToString("F5")+"; no fixed captureFramerate.\n");Destroy(capture);
   h.buff=16;h.formStage=2;h.energy=100;float start=Time.realtimeSinceStartup;for(int n=0;n<120;n++){h.Tick(Time.deltaTime);yield return new WaitForEndOfFrame();}float elapsed=Time.realtimeSinceStartup-start;File.WriteAllText(Path.Combine(folder,"Desempenho09.txt"),$"120 quadros, sem capturas: {elapsed:F3}s, {120/elapsed:F1} FPS. Amostra curta, nao benchmark.\n");Debug.Log("CIBIO_09_REVIEW_OK checks="+checks.Count+" animationFrames="+atlasReport.Count);Application.Quit();
  }
  public IEnumerator RunUi(string path)
  {
   g=GetComponent<RpgGame>();folder=path;Directory.CreateDirectory(folder);yield return new WaitForSecondsRealtime(1);ScreenCapture.CaptureScreenshot(Path.Combine(folder,"Menu09.png"));yield return new WaitForSecondsRealtime(.2f);g.StartGame(false);g.reviewPose=true;h=g.world.hero;g.messageUntil=0;h.direction=2;h.facing=Vector2.down;h.buff=16;h.formStage=2;h.Pose("idle",0);g.SnapCamera();yield return new WaitForSecondsRealtime(.5f);ScreenCapture.CaptureScreenshot(Path.Combine(folder,"Ascendente09.png"));var ui=GetComponent<RpgInterface>();ui.ReviewSkill(2);yield return new WaitForSecondsRealtime(.2f);ScreenCapture.CaptureScreenshot(Path.Combine(folder,"Skills09.png"));yield return new WaitForSecondsRealtime(.2f);ui.ReviewSkill(-1);ui.ReviewHelp(true);yield return new WaitForSecondsRealtime(.2f);ScreenCapture.CaptureScreenshot(Path.Combine(folder,"Controles09.png"));yield return new WaitForSecondsRealtime(.2f);ui.ReviewHelp(false);g.mode=3;yield return new WaitForSecondsRealtime(.2f);ScreenCapture.CaptureScreenshot(Path.Combine(folder,"Creditos09.png"));yield return new WaitForSecondsRealtime(.2f);Debug.Log("CIBIO_09_UI_REVIEW_OK");Application.Quit();
  }
  void Reset(){g.StartGame(false);g.reviewPose=true;g.progress.perks=7;g.progress.questStage=3;foreach(var e in g.world.enemies){e.transform.position=new Vector2(20,40);e.velocity=Vector2.zero;}h.transform.position=new Vector2(0,-10);g.messageUntil=0;}
  void Checks()
  {
   Reset();g.progress.questStage=0;g.HandleTransformInput(true);for(int n=0;n<210;n++)h.Tick(1/60f);Check(h.FormStage==0&&h.charging,"Segurar C nao transforma antes de soltar");g.HandleTransformInput(false);Check(h.FormStage==1,"Soltar carga completa ativa dourada");h.Tick(1.2f);g.HandleTransformInput(true);Check(h.FormStage==2&&h.energy==75&&h.transforming==1.7f,"Novo toque C ativa estagio 2 sem segunda carga ou missao");float duration=h.buff;g.HandleTransformInput(true);Check(h.buff==duration&&h.energy==75,"Manter C nao repete evolucao nem cobra novamente");g.HandleTransformInput(false);Check(h.FormStage==2&&!h.charging,"Soltar C conserva evolucao");Check(h.Family=="HeroAscendant"&&h.EnergyColor.b>h.EnergyColor.r,"Nova familia prateada e aura azul branca");
   foreach(string action in new[]{"idle","walk","run","jump","slash","thrust","backslash","spellcast","flight","hurt"}){var t=RpgArt.Texture("HeroAscendant_"+action);Check(t.width%192==0&&t.height==(action=="hurt"?192:768),"Celulas 192 sem redimensionamento: "+action);for(int d=0;d<4;d++){var s=RpgArt.Frame("HeroAscendant",action,d,0);Check(s&&s.pixelsPerUnit==64&&Mathf.Abs(s.bounds.size.x-3)<.001f,"Perspectiva/PPU/quad de 3 unidades: "+action+" "+d);}}
   Check(RpgArt.Texture("Transform_Ascendant09").width==1536,"Oito etapas exclusivas de transformacao");Check(Resources.Load<Font>("RpgArt/UI09-Regular")&&Resources.Load<Font>("RpgArt/UI09-Semibold"),"Tipografia profissional regular e semibold carregada");Check(GetComponent<RpgInterface>().SkillCount==5&&RpgArt.Texture("UI_Skills09").width==512,"Cinco skills e atlas original de icones");Check(RpgAudio.Clip("ascend_ignite")&&RpgAudio.Clip("sonic_boom"),"Novos efeitos de transformacao e sonic boom carregados");
   h.transforming=0;h.buff=20;h.formStage=1;h.energy=24;g.HandleTransformInput(true);Check(h.FormStage==1&&h.energy==24,"Energia insuficiente nao evolui");g.HandleTransformInput(false);h.energy=100;h.attackTimer=.4f;Check(!g.TryAscend(),"Ataque impede evolucao no meio do golpe");h.attackTimer=0;h.flying=true;h.flightHeight=1.9f;Check(g.TryAscend()&&h.flying,"Evolucao no ar conserva voo");h.Walk(Vector2.right,15,.1f);Check(h.velocity==Vector2.zero&&h.SonicDistance==0,"Cinematica trava movimento e contagem sonica");
   h.transforming=0;h.energy=100;h.transform.position=new Vector2(-16,-2);h.SetFlightControls(true,false);Check(h.FlightSpeed==15,"Impulso ascendente inicial 15 u/s");float distance=0;for(int n=0;n<200&&!h.SonicActive;n++){Vector2 before=h.Position;h.Walk(Vector2.right,h.FlightSpeed,1/60f);distance+=Vector2.Distance(before,h.Position);}Check(h.SonicActive&&distance>=18&&h.sonicBooms==1,"Boom exige 18 unidades realmente percorridas: measured="+distance+" sonic="+h.SonicDistance+" position="+h.Position);Check(h.FlightSpeed==24,"Sonic aumenta velocidade para 24 u/s");float energy=h.energy;h.Tick(.5f);Check(Mathf.Abs(energy-h.energy-9)<.01f,"Sonic consome 18 energia por segundo");for(int n=0;n<15;n++)h.Walk(Vector2.right,h.FlightSpeed,1/60f);Check(h.sonicBooms==1,"Um boom por impulso continuo");h.SetFlightControls(true,true);h.Walk(Vector2.right,h.FlightSpeed,.1f);Check(!h.SonicActive&&h.SonicDistance==0&&!h.flightBoosting,"Frear cancela sonic e reinicia distancia");
   h.SetFlightControls(true,false);h.ResetSonic();h.velocity=Vector2.zero;h.transform.position=new Vector2(-16,-2);for(int n=0;n<16;n++)h.Walk(Vector2.right,15,1/60f);float old=h.SonicDistance;h.velocity=Vector2.zero;h.Walk(Vector2.left,15,.1f);Check(h.SonicDistance<old,"Inversao de direcao reinicia embalo");h.Land();Check(!h.SonicActive&&h.SonicDistance==0,"Pouso limpa estado sonico");h.buff=.01f;h.Tick(.02f);Check(h.Family=="Hero"&&h.FormStage==0,"Expiracao devolve forma base");
   h.ResetMotion();h.buff=20;h.formStage=2;h.flying=true;h.SetFlightControls(true,false);h.transform.position=new Vector2(19,-10);h.velocity=Vector2.zero;var wall=new Rect(20,-12,1,4);g.world.obstacles.Add(wall);for(int n=0;n<150;n++)h.Walk(Vector2.right,15,1/60f);Check(!h.SonicActive&&h.SonicDistance<1&&h.Position.x<20,"Empurrar parede nao acumula distancia nem atravessa obstaculos");g.world.obstacles.Remove(wall);Check(RpgGame.SaveKey=="Cibio.RPG.v3.Progress","Chave do save preservada");
  }
  IEnumerator Frames(int count,Vector2 move,bool boost=false,bool brake=false){for(int n=0;n<count;n++){h.SetFlightControls(boost,brake);h.Walk(move,h.flying?h.FlightSpeed:h.GroundSpeed(boost),1/24f,boost);h.Tick(1/24f);g.dashCooldown=Mathf.Max(0,g.dashCooldown-1/24f);g.waveCooldown=Mathf.Max(0,g.waveCooldown-1/24f);g.boltCooldown=Mathf.Max(0,g.boltCooldown-1/24f);yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.Combine(folder,$"Frame_{frame++:D4}.png"));}}
  IEnumerator Live(float seconds,Vector2 move,bool boost=false){while(seconds>0){float dt=Time.deltaTime;h.SetFlightControls(boost,false);h.Walk(move,h.flying?h.FlightSpeed:h.GroundSpeed(boost),dt,boost);h.Tick(dt);seconds-=dt;yield return null;}}
  void OnDisable(){Time.captureFramerate=0;}
 }
}
